set +x; set -eu; umask 077; [ "$STACKKITS_OWNER_HASH_FILE" = /run/secrets/adguard-owner-bcrypt ]; [ -s "$STACKKITS_OWNER_HASH_FILE" ]; [ -n "$STACKKITS_DNS_CONFIG_JSON" ]; hash=$(base64 -d < "$STACKKITS_OWNER_HASH_FILE"); case "$hash" in '$2a$'*|'$2b$'*|'$2y$'*) ;; *) exit 1 ;; esac; [ "${#hash}" = 60 ]; case "$hash" in *[!A-Za-z0-9./$]*) exit 1 ;; esac; conf=/opt/adguardhome/conf; [ ! -L "$conf" ]; mkdir -p "$conf"; chmod 700 "$conf"; file=$(mktemp "$conf/.AdGuardHome.XXXXXX"); trap 'rm -f "$file"' EXIT HUP INT TERM; printf '%s\n' "$STACKKITS_DNS_CONFIG_JSON" | sed "s|@@OWNER_BCRYPT@@|$hash|g" > "$file"; chmod 600 "$file"; mv -f "$file" "$conf/AdGuardHome.yaml"; trap - EXIT HUP INT TERM; unset hash file STACKKITS_DNS_CONFIG_JSON STACKKITS_OWNER_HASH_FILE; exec /opt/adguardhome/AdGuardHome -c "$conf/AdGuardHome.yaml" -w /opt/adguardhome/work --no-check-update
